To solve this problem, you need to implement a **Global Tooltip Provider**.

Since Next.js components are isolated, you cannot rely on `useState` inside a single component to track the state of *all* tooltips. Instead, you must lift the state up to a Context Provider that wraps your entire application (or the specific layout where the tooltips live).

Here is a complete, copy-pasteable solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider
First, create a file to manage the global state of the tooltips.

`src/context/TooltipContext.tsx`

```tsx
'use client';

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of a tooltip
interface TooltipData {
  id: string;
  content: string;
  x: number;
  y: number;
}

interface TooltipContextType {
  activeTooltip: TooltipData | null;
  openTooltip: (content: string, x: number, y: number) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeTooltip, setActiveTooltip] = useState<TooltipData | null>(null);

  const openTooltip = useCallback((content: string, x: number, y: number) => {
    // Generate a unique ID to ensure we can close it later if needed
    const id = Math.random().toString(36).substr(2, 9);
    setActiveTooltip({ id, content, x, y });
  }, []);

  const closeTooltip = useCallback(() => {
    setActiveTooltip(null);
  }, []);

  return (
    <TooltipContext.Provider value={{ activeTooltip, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

### 2. Create the Tooltip Component
This component is stateless regarding the "open/close" logic. It simply reads the context to see if it should render.

`src/components/Tooltip.tsx`

```tsx
'use client';

import React from 'react';
import { useTooltip } from '@/context/TooltipContext';

interface TooltipProps {
  content: string;
  x: number;
  y: number;
}

export const Tooltip: React.FC<TooltipProps> = ({ content, x, y }) => {
  const { activeTooltip, closeTooltip } = useTooltip();

  // If the tooltip in context matches this one, render it
  if (activeTooltip?.content === content && activeTooltip?.x === x && activeTooltip?.y === y) {
    return (
      <div
        style={{
          position: 'absolute',
          left: x,
          top: y,
          zIndex: 9999,
          pointerEvents: 'none', // Let clicks pass through to the trigger
        }}
      >
        <div className="bg-black text-white text-xs px-2 py-1 rounded shadow-lg whitespace-nowrap">
          {content}
        </div>
        {/* Little arrow */}
        <div className="absolute left-1/2 -bottom-1 -translate-x-1/2 w-2 h-2 bg-black rotate-45"></div>
      </div>
    );
  }

  return null;
};
```

