$height = 600;
$iterations = 100; // Liczba iteracji (im więcej, tym bardziej szczegółowy, ale wolniejszy)
$minReal = -2.0;
$maxReal = 1.0;
$minImag = -1.5;
$maxImag = 1.5;

// Inicjalizacja obrazu (gdzie 0 to czarny piksel, 255 to biały)
// Używamy array zamiast GD, aby nie wymagać instalacji biblioteki graficznej
$image = array_fill(0, $height, array_fill(0, $width, 0));

// Pętla po każdym pikselu
for ($y = 0; $y < $height; $y++) {
    for ($x = 0; $x < $width; $x++) {

        // Mapowanie współrzędnych piksela na płaszczyznę zespoloną
        // Skalujemy szerokość i wysokość obrazu do zakresu matematycznego
        $real = $minReal + ($x / $width) * ($maxReal - $minReal);
        $imag = $minImag + ($y / $height) * ($maxImag - $minImag);

        // Zmienne dla algorytmu Mandelbrota: z = x + iy
        $zReal = 0.0;
        $zImag = 0.0;
        $cReal = $real;
        $cImag = $imag;

        $escape = false;

