    iconPath: '/assets/icon.png',
    tooltip: 'Discord'
});

// Listen for a response from the main process
ipcRenderer.on('tray-updated', (event, status) => {
    console.log(`Tray status updated: ${status}`);
});
```

**Main Process (JavaScript):**
```javascript
