  // 1. Define the Shadow DOM
  static get observedAttributes() {
    // We observe attributes that need to be passed to the internal input
    // Highlights: "list is only a getter on HTMLInputElement... handled in attributeChangedCallback"
    return ['value', 'disabled', 'required', 'list', 'validators'];
  }

  constructor() {
    super();

    // 2. Setup ElementInternals for Form Association
    // Highlight: "When the formAssociated property is set to true... calling attachInternals()"
    this.attachInternals();

    // Highlight: "It's typical to set another property on the class to an instance of ElementInternals"
    this._internals = this.internals;

    // Highlight: "appears the structure of the template is just enough to support the input and validation messages"
    this.attachShadow({ mode: 'open' });

    this.shadowRoot.innerHTML = `
