std::string bytesToBase64(const unsigned char* data, size_t len) {
    BIO* bio = BIO_new(BIO_f_base64());
    BIO* set = BIO_new(BIO_s_mem());
    BIO* out = BIO_push(bio, set);

    BIO_write(out, data, len);
    BIO_flush(out);

    char* buffer = nullptr;
    long len_out = BIO_get_mem_data(out, &buffer);
    std::string result(buffer, len_out);

    BIO_free_all(out);
    return result;
}

// Helper function to convert Base64 string to bytes
std::vector<unsigned char> base64ToBytes(const std::string& input) {
    BIO* bio = BIO_new_mem_buf(input.c_str(), -1);
