        createBucketIfNotExists(couchbaseSettings)

        bucket = cluster.bucket(bucketName)
        bucket.waitUntilReady(Duration.ofSeconds(10))

        createIndexes()

        // Run migrations in a background thread
        runMigrationsInBackground()
    }

